 let segment = ((phase * 4.0).floor() as usize).min(3);
 let u = phase * 4.0 - segment as f32;
 let secants: [f32;4] = std::array::from_fn(|i| (profile[i+1]-profile[i])*4.0);
 let mut tangents = [0.0f32;5];
 for i in 1..4 { let before=secants[i-1]; let after=secants[i]; if before>0.0 && after>0.0 { tangents[i]=2.0*before*after/(before+after); } }
