#[test]
fn decoded_glb_retains_zero_weights() {
    let mut json = br#"{"asset":{"version":"2.0"},"buffers":[{"byteLength":28}],"bufferViews":[{"buffer":0,"byteOffset":0,"byteLength":12},{"buffer":0,"byteOffset":12,"byteLength":16}],"accessors":[{"bufferView":0,"componentType":5126,"count":1,"type":"VEC3","min":[0,0,0],"max":[0,0,0]},{"bufferView":1,"componentType":5126,"count":1,"type":"VEC4"}],"meshes":[{"primitives":[{"attributes":{"POSITION":0,"WEIGHTS_0":1}}]}]}"#.to_vec();
    while json.len() % 4 != 0 { json.push(b' '); }
    let bin = [0_u8; 28];
    let length = 12 + 8 + json.len() + 8 + bin.len();
    let mut glb = b"glTF".to_vec();
    glb.extend(2_u32.to_le_bytes()); glb.extend((length as u32).to_le_bytes());
    glb.extend((json.len() as u32).to_le_bytes()); glb.extend(b"JSON"); glb.extend(json);
    glb.extend((bin.len() as u32).to_le_bytes()); glb.extend(b"BIN\0"); glb.extend(bin);
    let doc = gltf::Gltf::from_slice(&glb).unwrap();
    let primitive = doc.meshes().next().unwrap().primitives().next().unwrap();
    let weights = primitive.reader(|_| doc.blob.as_deref()).read_weights(0).unwrap().into_f32().next().unwrap();
    assert_eq!(weights, [0.0; 4]);
}

